-- Hydroforming - Tool life
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Hydroforming - Tool life$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Hydroforming - Tool life$q$, 'process', 'single', false, true, true, $q$Parts one hydroform tool forms: tblToolLife by the material's type (defaultToolLife when the type is not listed), times the life its coating gives (tblToolCoating; defaultToolingCoatingType, or highStrengthMatlToolingCoatingType for a material above highStrengthMatlThreshold).$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$Parts one hydroform tool forms: tblToolLife by the material's type (defaultToolLife when the type is not listed), times the life its coating gives (tblToolCoating; defaultToolingCoatingType, or highStrengthMatlToolingCoatingType for a material above highStrengthMatlThreshold).$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Parts per Tool$q$, $q$Parts per Tool$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Coating Life Factor$q$, $q$Coating Life Factor$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Tool Life$q$, $q$Tool Life$q$, $q$calculated$q$, NULL, NULL, NULL, NULL, $q${Parts per Tool} * {Coating Life Factor}$q$, 3, false);
END
$calc$;

-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Hydroforming - Hydroform$q$, 13, 1),
    ($q$Hydroforming - Offline blank$q$, 8, 1),
    ($q$Hydroforming - Clean tooling$q$, 4, 0),
    ($q$Hydroforming - Throw pad$q$, 8, 0),
    ($q$Hydroforming - Hand adjusting$q$, 3, 0),
    ($q$Hydroforming - Parts per tray$q$, 11, 0),
    ($q$Hydroforming - Blanking force$q$, 5, 0),
    ($q$Hydroforming - Blank$q$, 7, 0),
    ($q$Hydroforming - Material$q$, 3, 0),
    ($q$Hydroforming - Hydroform tool$q$, 45, 0),
    ($q$Hydroforming - Tool life$q$, 3, 0)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Sheet Metal - Hydroforming$q$ AND (m.is_active OR m.machine_class IS NULL)) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1110: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
